-- 값의 출처: lib/factory/projectToolSettingsSchema.ts 의 SAESSAK_HUB_SETTINGS 주석.
INSERT INTO "factory_project_tool_settings" ("appSlug", "version", "settings", "updatedBy") VALUES ('saessak-hub', 1, '{"version":1,"methods":{"image-prop":{"allowed":["codex","pixellab","claude"],"default":"codex"},"image-scene":{"allowed":["codex","pixellab"],"default":"codex"},"motion-game":{"allowed":["claude","pixellab","codex"],"default":"claude"},"motion-clip":{"allowed":["manual","codex"],"default":"manual"}},"results":{"allowed_kinds":["image-prop","image-scene","motion-game","motion-clip"],"default_kind":"image-prop"},"spec":{"cell_size":32,"size_group":"길가 건물·나무·마당 소품·세트 소품·연구/교육/휴게실"},"style":{"outline_color":"#3A2820","max_colors":56,"preset":"hub","notes":"소품은 투명 배경(마진 20% 이하·잘림 없음, check_rules.dart:35·38). 정면에서 약간 위 시점, 진한 갈색 외곽선 1칸 두께, 색 2~3단 음영·그라데이션 없음. 작은 그림은 32색 이하. 자세한 규칙: styles/hub/preset.json"},"cost":{"pixellab_per_job":3,"pixellab_per_month":30},"aliases":{"직원":["staff","staff_walk"],"손님":["customer","cust"]}}', '정비(새싹 허브 코드 기준)') ON CONFLICT ("appSlug") DO NOTHING;
